// Asset normalization only; source artwork is generated by image_gen and preserved.
const sharp=require('sharp');
const fs=require('node:fs/promises');
const path=require('node:path');
const assert=require('node:assert/strict');
const root=path.resolve(__dirname,'..');
const source=path.join(root,'art/source-v2');
const output=path.join(root,'assets');
const manifest=[];
async function cell(file,x0,y0,x1,y1,trim=false){
  const m=await sharp(file).metadata();
  const left=Math.round(x0*m.width)+2,top=Math.round(y0*m.height)+2;
  const width=Math.round(x1*m.width)-left-2,height=Math.round(y1*m.height)-top-2;
  const b=await sharp(file).extract({left,top,width,height}).toBuffer();
  return trim?sharp(b).trim({threshold:12}).toBuffer():b;
}
async function normalized(buf,scale){
  const m=await sharp(buf).metadata();
  const width=Math.max(1,Math.round(m.width*scale)),height=Math.max(1,Math.round(m.height*scale));
  assert(width<=120&&height<=112);
  const {data,info}=await sharp(buf).resize(width,height,{kernel:'nearest'}).ensureAlpha().raw().toBuffer({resolveWithObject:true});
  for(let i=3;i<data.length;i+=4)data[i]=data[i]<100?0:255;
  const clean=await sharp(data,{raw:info}).png().toBuffer();
  return sharp({create:{width:128,height:128,channels:4,background:'#00000000'}})
    .composite([{input:clean,left:Math.floor((128-width)/2),top:120-height}]).png({palette:true,colours:64,dither:0}).toBuffer();
}
async function strip(id,state,frames){
  const name=`motion/${id}_${state}.png`;
  await sharp({create:{width:128*frames.length,height:128,channels:4,background:'#00000000'}})
    .composite(frames.map((input,i)=>({input,left:128*i,top:0}))).png({palette:true,colours:64,dither:0}).toFile(path.join(output,name));
  manifest.push({file:name,id,state,frames:frames.length,frameSize:128});
}
async function poses(job){
  const file=path.join(source,job.key+'.png');
  const ids=job.ids;
  for(let i=0;i<ids.length;i++){
    const row=job.kind==='enemy'?Math.floor(i/2):i;
    const start=job.kind==='enemy'?(i%2)*3:0;
    const count=job.kind==='enemy'?3:4;
    const xs=job.x,ys=job.y;
    const pieces=await Promise.all(Array.from({length:count},(_,j)=>cell(file,xs[start+j],ys[row],xs[start+j+1],ys[row+1],true)));
    const id=(job.kind==='enemy'?'enemy_':'')+ids[i];
    const idle=await fs.readFile(path.join(output,id+'_idle.png'));
    const idleSize=await sharp(await sharp(idle).trim().toBuffer()).metadata();
    const sizes=await Promise.all(pieces.map(b=>sharp(b).metadata()));
    const scale=Math.min(...sizes.map(m=>120/m.width),...sizes.map(m=>Math.min(112,idleSize.height+16)/m.height));
    const p=await Promise.all(pieces.map(b=>normalized(b,scale)));
    if(job.kind==='enemy'){
      await strip(id,'attack',[idle,p[1],p[0],idle]);
      await strip(id,'cast',[idle,p[1],p[1],idle]);
      await strip(id,'hit',[idle,p[2],p[2],idle]);
    }else{
      await strip(id,'guard',[idle,p[0],p[0],idle]);
      await strip(id,'hit',[idle,p[1],p[1],idle]);
      await strip(id,'cast',[idle,p[2],p[2],idle]);
      await strip(id,'ultimate',[idle,p[2],p[3],idle]);
    }
  }
}
(async()=>{
  const jobs=JSON.parse(await fs.readFile(path.join(source,'jobs.json'),'utf8'));
  for(const folder of ['maps','cards','motion'])await fs.mkdir(path.join(output,folder),{recursive:true});
  for(const job of jobs){
    const file=path.join(source,job.key+'.png');
    if(job.kind==='battle'){
      const name=`maps/${job.region}-battle.png`;
      await sharp(file).resize(640,360,{fit:'cover',kernel:'nearest'}).png({palette:true,colours:96,dither:0}).toFile(path.join(output,name));
      manifest.push({file:name,region:job.region,width:640,height:360});
    }else if(job.kind==='routes'){
      for(const [i,region]of ['coast','forest','spire','lahai'].entries()){
        const name=`maps/${region}-route.png`;
        await sharp(await cell(file,i/4,0,(i+1)/4,1)).resize(320,640,{fit:'fill',kernel:'nearest'}).png({palette:true,colours:96,dither:0}).toFile(path.join(output,name));
        manifest.push({file:name,region,width:320,height:640});
      }
    }else if(job.kind==='icons'){
      for(const [i,id]of job.ids.entries()){
        const name=`maps/node-${id}.png`;
        await sharp(await cell(file,(i%4)/4,Math.floor(i/4)/2,(i%4+1)/4,(Math.floor(i/4)+1)/2,true))
          .resize(32,32,{fit:'contain',kernel:'nearest',background:'#00000000'}).png({palette:true,colours:32,dither:0}).toFile(path.join(output,name));
        manifest.push({file:name,id,width:32,height:32});
      }
    }else if(job.kind==='cards'){
      for(const [i,id]of job.ids.entries()){
        const row=Math.floor(i/job.cols),col=i%job.cols;
        const name=`cards/${id}.png`;
        await sharp(await cell(file,col/job.cols,row/job.rows,(col+1)/job.cols,(row+1)/job.rows))
          .resize(144,96,{fit:'cover',kernel:'nearest'}).png({palette:true,colours:80,dither:0}).toFile(path.join(output,name));
        manifest.push({file:name,id,width:144,height:96});
      }
    }else if(job.kind==='hero'||job.kind==='enemy')await poses(job);
    else if(job.kind==='mecha'){
      const pieces=await Promise.all(Array.from({length:8},(_,i)=>cell(file,(i%4)/4,Math.floor(i/4)/2,(i%4+1)/4,(Math.floor(i/4)+1)/2,true)));
      const sizes=await Promise.all(pieces.map(b=>sharp(b).metadata()));
      const scale=Math.min(...sizes.flatMap(m=>[120/m.width,108/m.height]));
      const p=await Promise.all(pieces.map(b=>normalized(b,scale)));
      await fs.writeFile(path.join(output,'aemMecha_idle.png'),p[0]);await fs.writeFile(path.join(output,'aemMecha.png'),p[0]);
      await strip('aemMecha','attack',p.slice(0,4));
      await fs.copyFile(path.join(output,'motion/aemMecha_attack.png'),path.join(output,'aemMecha_attack.png'));
      for(const[state,index]of [['guard',4],['hit',5],['cast',6],['ultimate',7]])await strip('aemMecha',state,[p[0],state==='ultimate'?p[6]:p[index],p[index],p[0]]);
    }
  }
  const html=await fs.readFile(path.join(root,'index.html'),'utf8');
  const cardSource=html.slice(html.indexOf('const CD={'),html.indexOf('const REWARD_POOL='));
  const cards=[...cardSource.matchAll(/^  (\w+):\{n:/gm)].map(m=>m[1]);
  assert.equal(cards.length,70);
  for(const id of cards)assert(manifest.some(a=>a.file===`cards/${id}.png`),`missing card: ${id}`);
  const motion=manifest.filter(a=>a.frames);
  assert.equal(motion.length,121);
  for(const entry of motion){
    const {data,info}=await sharp(path.join(output,entry.file)).ensureAlpha().raw().toBuffer({resolveWithObject:true});
    assert.equal(info.width,512);assert.equal(info.height,128);
    for(let frame=0;frame<4;frame++){
      let empty=0,visible=0;
      for(let y=0;y<128;y++)for(let x=frame*128;x<(frame+1)*128;x++)data[(y*512+x)*4+3]?visible++:empty++;
      assert(empty>1500&&visible>100,`${entry.file}: invalid frame ${frame}`);
    }
  }
  await fs.writeFile(path.join(root,'art/manifest-v2.json'),JSON.stringify(manifest,null,2)+'\n');
  const tiles=await Promise.all(cards.map(async(id,i)=>({input:await fs.readFile(path.join(output,'cards',id+'.png')),left:(i%7)*152+4,top:Math.floor(i/7)*104+4})));
  await sharp({create:{width:1064,height:1040,channels:4,background:'#111b30'}}).composite(tiles).png().toFile(path.join(root,'art/cards-contact-sheet.png'));
  console.log(`PASS: ${cards.length} card illustrations, 8 region images, ${motion.length} motion strips with transparent frames.`);
})().catch(e=>{console.error(e);process.exitCode=1});
